public static String normalize(String text) {
    return text.strip().toLowerCase(java.util.Locale.ROOT);
}

public static String normalize(String text) {
    return text.strip().toUpperCase(java.util.Locale.ROOT);
}

public static RailixValue quoteOrder(
        RailixValue items,
        BigDecimal discountPercent,
        BigDecimal taxPercent,
        boolean express) {

    var errors = new java.util.ArrayList<RailixValue>();
    var pricedItems = new java.util.ArrayList<RailixValue>();
    var subtotal = BigDecimal.ZERO;
    var hundred = new BigDecimal("100");
    var rounding = java.math.RoundingMode.HALF_UP;

    if (discountPercent.signum() < 0 || discountPercent.compareTo(hundred) > 0) {
        errors.add(RailixValue.string("Discount must be between 0 and 100."));
    }
    if (taxPercent.signum() < 0 || taxPercent.compareTo(hundred) > 0) {
        errors.add(RailixValue.string("Tax must be between 0 and 100."));
    }

    if (items instanceof RailixValue.ArrayValue array && !array.values().isEmpty()) {
        for (int index = 0; index < array.values().size(); index++) {
            var item = array.values().get(index);

            if (!(item instanceof RailixValue.ObjectValue line)) {
                errors.add(RailixValue.string(
                        "Item " + (index + 1) + " must be an object."));
                continue;
            }

            var sku = line.values().get("sku");
            var quantity = line.values().get("quantity");
            var price = line.values().get("unitPrice");

            if (!(sku instanceof RailixValue.StringValue code)
                    || code.value().isBlank()
                    || !(quantity instanceof RailixValue.NumberValue count)
                    || count.value().signum() <= 0
                    || count.value().stripTrailingZeros().scale() > 0
                    || !(price instanceof RailixValue.NumberValue amount)
                    || amount.value().signum() < 0) {
                errors.add(RailixValue.string(
                        "Item " + (index + 1)
                        + " needs a nonblank sku, positive integer quantity"
                        + " and nonnegative unitPrice."));
                continue;
            }

            var unitPrice = amount.value().setScale(2, rounding);
            var lineTotal = unitPrice.multiply(count.value());
            subtotal = subtotal.add(lineTotal);

            pricedItems.add(RailixValue.object(java.util.Map.of(
                    "sku", RailixValue.string(code.value().strip()),
                    "quantity", RailixValue.number(count.value()),
                    "unitPrice", RailixValue.number(unitPrice),
                    "lineTotal", RailixValue.number(lineTotal)
            )));
        }
    } else {
        errors.add(RailixValue.string("Items must be a nonempty array."));
    }

    if (!errors.isEmpty()) {
        return RailixValue.object(java.util.Map.of(
                "valid", RailixValue.bool(false),
                "errors", RailixValue.array(errors)
        ));
    }

    var discountAmount = subtotal.multiply(discountPercent)
            .divide(hundred, 2, rounding);
    var discountedSubtotal = subtotal.subtract(discountAmount);

    var shipping = express
            ? new BigDecimal("15.00")
            : discountedSubtotal.compareTo(hundred) >= 0
                    ? new BigDecimal("0.00")
                    : new BigDecimal("5.00");

    var taxableAmount = discountedSubtotal.add(shipping);
    var taxAmount = taxableAmount.multiply(taxPercent)
            .divide(hundred, 2, rounding);

    return RailixValue.object(java.util.Map.of(
            "valid", RailixValue.bool(true),
            "items", RailixValue.array(pricedItems),
            "subtotal", RailixValue.number(subtotal),
            "discount", RailixValue.number(discountAmount),
            "shipping", RailixValue.number(shipping),
            "tax", RailixValue.number(taxAmount),
            "total", RailixValue.number(taxableAmount.add(taxAmount)),
            "shippingMode", RailixValue.string(express ? "express" : "standard")
    ));
}
